from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak, KeepTogether

OUT = "output/pdf/Jaya_Logistics_Driver_Mobile_Live_Workflow_Guide.pdf"
W, H = A4
styles = getSampleStyleSheet()
styles.add(ParagraphStyle(name="TitleX", parent=styles["Title"], fontName="Helvetica-Bold", fontSize=25, leading=30, textColor=colors.HexColor("#0F172A"), spaceAfter=8))
styles.add(ParagraphStyle(name="SubX", parent=styles["Normal"], fontSize=11, leading=16, textColor=colors.HexColor("#475569"), spaceAfter=14))
styles.add(ParagraphStyle(name="H1X", parent=styles["Heading1"], fontName="Helvetica-Bold", fontSize=16, leading=20, textColor=colors.HexColor("#0F172A"), spaceBefore=8, spaceAfter=8))
styles.add(ParagraphStyle(name="H2X", parent=styles["Heading2"], fontName="Helvetica-Bold", fontSize=12, leading=15, textColor=colors.HexColor("#0F172A"), spaceBefore=7, spaceAfter=4))
styles.add(ParagraphStyle(name="BodyX", parent=styles["BodyText"], fontName="Helvetica", fontSize=10.2, leading=14.5, textColor=colors.HexColor("#1E293B"), spaceAfter=5))
styles.add(ParagraphStyle(name="SmallX", parent=styles["BodyText"], fontName="Helvetica", fontSize=8.7, leading=11, textColor=colors.HexColor("#475569"), spaceAfter=2))
styles.add(ParagraphStyle(name="FlowX", parent=styles["BodyText"], fontName="Helvetica-Bold", fontSize=8.2, leading=10, alignment=1, textColor=colors.white))

def p(text, style="BodyX"): return Paragraph(text, styles[style])
def bullet(text): return Paragraph(f"<bullet>&bull;</bullet> {text}", styles["BodyX"])
def box(title, text, bg="#E0F2FE"):
    t = Table([[p(f"<b>{title}</b><br/>{text}")]], colWidths=[170*mm])
    t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,-1),colors.HexColor(bg)),("BOX",(0,0),(-1,-1),0.6,colors.HexColor("#CBD5E1")),("LEFTPADDING",(0,0),(-1,-1),10),("RIGHTPADDING",(0,0),(-1,-1),10),("TOPPADDING",(0,0),(-1,-1),8),("BOTTOMPADDING",(0,0),(-1,-1),8)]))
    return t
def flow(items):
    t=Table([[Paragraph(x,styles["FlowX"]) for x in items]],colWidths=[170*mm/len(items)]*len(items))
    t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,-1),colors.HexColor("#0F172A")),("INNERGRID",(0,0),(-1,-1),1,colors.HexColor("#FBBF24")),("BOX",(0,0),(-1,-1),0.5,colors.HexColor("#0F172A")),("VALIGN",(0,0),(-1,-1),"MIDDLE"),("TOPPADDING",(0,0),(-1,-1),10),("BOTTOMPADDING",(0,0),(-1,-1),10)]))
    return t
def table(rows, widths):
    t=Table([[p(cell, "SmallX") for cell in row] for row in rows],colWidths=widths,repeatRows=1)
    t.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#0F172A")),("TEXTCOLOR",(0,0),(-1,0),colors.white),("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),("GRID",(0,0),(-1,-1),0.35,colors.HexColor("#CBD5E1")),("VALIGN",(0,0),(-1,-1),"TOP"),("LEFTPADDING",(0,0),(-1,-1),6),("RIGHTPADDING",(0,0),(-1,-1),6),("TOPPADDING",(0,0),(-1,-1),6),("BOTTOMPADDING",(0,0),(-1,-1),6),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#F8FAFC")])]))
    return t
def footer(canvas, doc):
    canvas.saveState(); canvas.setFont("Helvetica",8); canvas.setFillColor(colors.HexColor("#64748B")); canvas.drawString(20*mm,11*mm,"Jaya Logistics - Driver Mobile Live Workflow Guide"); canvas.drawRightString(W-20*mm,11*mm,f"Page {doc.page}"); canvas.restoreState()

s=[]
