s += [p("Part 3 - Driver installation and first login", "H1X"),p("Give these steps directly to every driver."),p("1. Install", "H2X"),bullet("Receive the official Jaya Logistics Driver APK from your office."),bullet("Open the file on the Android phone. If Android asks, allow installation from this source."),bullet("Open the app. It must show the <b>Jaya Logistics Driver</b> login screen, not the normal ERP website home page."),p("2. Login and create personal PIN", "H2X"),bullet("Enter the mobile number registered by the office and the temporary PIN provided by dispatch."),bullet("On first login, enter the temporary PIN again, choose a new private PIN and confirm it."),bullet("Never share the new PIN with another driver."),p("3. Phone approval", "H2X"),bullet("The app may show <b>waiting for dispatcher approval</b>. Inform dispatch that you have logged in."),bullet("Dispatch approves the phone in Driver Mobile Setup. Tap <b>Refresh approval</b> in the app."),bullet("After approval, assigned trips appear automatically."),box("New or replaced phone","Install the app again, login and ask dispatch to approve the new phone. The old phone should be revoked by dispatch.","#E0F2FE"),PageBreak()]

s += [p("Part 4 - Driver trip screens and actions", "H1X"),table([["Screen","What the driver does"],["Login","Enter registered mobile number and personal PIN."],["Set your own PIN","Shown only after a temporary PIN reset. Save a new private PIN before using the phone."],["Waiting for approval","Wait for office approval, then tap Refresh approval."],["My active trips","See only trips assigned to this driver. Select the correct trip."],["Trip details","Read Loading reference, vehicle, pickup and destination information."],["Trip action","Tap the available action: Start trip, At pickup, Start delivery, Arrived at stop, Confirm delivery or Complete."],["Report an issue","Use this for breakdown, traffic, fuel or waiting problems."]],[43*mm,127*mm]),p("Starting a trip", "H2X"),flow(["Open assigned trip","Tap Start trip","Allow permissions","Tracking notification appears","Continue delivery"]),bullet("The app asks for location and notification permission. Choose <b>Precise location</b>."),bullet("For tracked delivery, set Android location permission to <b>Allow all the time</b>. The trip will not start until required location permissions are ready."),bullet("After start, confirm that the tracking notification remains visible."),p("During delivery", "H2X"),bullet("Keep Location/GPS, mobile data or Wi-Fi and phone battery available."),bullet("Do not force-close the app while the trip is active."),bullet("Follow the trip action buttons in order. Contact dispatch if the wrong trip or stop is shown."),PageBreak()]

s += [p("Part 5 - Android permissions and quick help", "H1X"),p("Driver phone checklist", "H2X"),table([["Setting","What to do"],["Location","Turn Location on. Choose Precise location and Allow all the time for the Driver app."],["Notifications","Allow notifications. A running tracking notification is expected during an active trip."],["Battery","Set the app battery use to Unrestricted / Do not optimise if the phone has that option."],["Data / Wi-Fi","Keep either mobile data or Wi-Fi connected. Android does not ask a separate permission for this."],["Camera / files","Allow only when the app asks for a delivery photo or document upload."]],[45*mm,125*mm]),p("Common issues", "H2X"),table([["Problem","Driver / office action"],["Cannot login","Check registered mobile number. Ask Admin to reset PIN and confirm mobile access is enabled."],["No trip shown","Office must assign the Loading entry to the correct driver and approve the phone."],["App says waiting for approval","Ask office to approve the device, then tap Refresh approval."],["Trip cannot start","Turn on Precise Location and Allow all the time in Android settings."],["Tracking not updating","Keep GPS/data on, do not force-close app, allow notifications and remove battery restriction."],["Changed phone / number","Tell Admin. The driver profile and device must be reviewed again."]],[45*mm,125*mm]),box("Before every real delivery","Driver is Registered - mobile access Enabled - personal PIN works - phone Approved - correct Loading entry Assigned - location settings allowed - active trip tracking notification visible.","#DCFCE7"),Spacer(1,8),p("Support contact", "H2X"),p("For driver access, PIN, assignment or device approval, contact your Jaya Logistics dispatch / Admin team. Do not share passwords or signing secrets through WhatsApp.","BodyX")]

